  margin-bottom: 1.75rem;
}

/* ========= Form fields ========= */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-bottom: 1.4rem;
}

label {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-label);
}

.required-marker {
  color: #ff8f8f;
  margin-left: 2px;
}

.optional-label {
  font-weight: 400;
  font-size: 0.8rem;
