html { font-size: 16px; }

body {
  background-color: var(--bg-page);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", Helvetica, Arial, sans-serif;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
}

/* ========= Skip link ========= */
.skip-link {
  position: absolute;
  top: -100%;
  left: 0.5rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  border-radius: var(--radius);
  text-decoration: none;
  z-index: 100;
  transition: top var(--transition);
}
.skip-link:focus { top: 0.5rem; }

/* ========= Screen-reader only ========= */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ========= Card ========= */
.form-card {
  background: var(--bg-card);
  border: 1px solid var(--border-idle);
  border-radius: 12px;
  padding: 2.5rem 2rem;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.45);
}

h1 {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.4rem;
}

.form-intro {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 1.75rem;
}

/* ========= Form fields ========= */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-bottom: 1.4rem;
}

label {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-label);
}

.required-marker {
  color: #ff8f8f;
  margin-left: 2px;
}

.optional-label {
  font-weight: 400;
  font-size: 0.8rem;
  color: var(--text-secondary);
}

input {
  background: var(--bg-input);
  border: 1px solid var(--border-idle);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 1rem;
  padding: 0.65rem 0.9rem;
  width: 100%;
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
}

input::placeholder { color: var(--text-secondary); opacity: 0.6; }

input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(108, 138, 255, 0.25);
}

input[aria-invalid="true"] {
  border-color: var(--border-error);
}
input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(255, 107, 107, 0.25);
}

/* ========= Help & error text ========= */
.field-help {
  font-size: 0.8rem;
  color: var(--help-text);
  margin: 0;
}

.field-error {
  font-size: 0.8rem;
  color: var(--error-text);
  margin: 0;
  display: flex;
  align-items: flex-start;
  gap: 0.3rem;
}

.field-error[hidden] { display: none; }

/* ========= Submit button ========= */
.submit-btn {
  display: block;
  width: 100%;
  margin-top: 0.5rem;
  padding: 0.75rem 1.25rem;
  background: var(--btn-bg);
  border: none;
  border-radius: var(--radius);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition);
  outline: none;
}

.submit-btn:hover { background: var(--btn-hover); }

.submit-btn:focus-visible {
  box-shadow: 0 0 0 3px rgba(108, 138, 255, 0.45);
}

/* ========= Success message ========= */
.success-message {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  background: var(--success-bg);
  border: 1px solid var(--success-border);
  border-radius: var(--radius);
  padding: 1.1rem 1.25rem;
  color: var(--success-text);
  font-size: 0.95rem;
  margin-top: 1.5rem;
}
.success-message[hidden] { display: none; }
.success-icon { width: 1.5rem; height: 1.5rem; flex-shrink: 0; }

/* ========= Reduced motion ========= */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ========= High-contrast / Forced colors ========= */
@media (forced-colors: active) {
  input { border: 2px solid ButtonText; }
  input:focus { outline: 2px solid Highlight; }
  .submit-btn { border: 2px solid ButtonText; }
}

