    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content">
      <div class="form-card">
        <h1>Contact Support</h1>
        <p class="form-intro">Fields marked with <span aria-hidden="true">*</span><span class="sr-only">an asterisk</span> are required.</p>

        <div role="status" id="form-status" class="sr-only"></div>

        <form id="contact-form" novalidate aria-label="Contact support form">

          <div class="form-field">
            <label for="full-name">
              Full name <span aria-hidden="true" class="required-marker">*</span>
            </label>
            <input
              id="full-name"
              name="full-name"
              type="text"
              required
              autocomplete="name"
              aria-describedby="full-name-error"
            />
            <p id="full-name-error" class="field-error" role="alert" hidden>
              Error: Full name is required.
            </p>
          </div>

          <div class="form-field">
            <label for="email">
              Email address <span aria-hidden="true" class="required-marker">*</span>
            </label>
            <input
              id="email"
              name="email"
              type="email"
              required
              autocomplete="email"
              aria-describedby="email-error"
            />
            <p id="email-error" class="field-error" role="alert" hidden>
              Error: Enter a valid email address, e.g. name@example.com.
            </p>
          </div>

          <div class="form-field">
            <label for="phone">Phone number <span class="optional-label">(optional)</span></label>
            <input
              id="phone"
              name="phone"
              type="tel"
              autocomplete="tel"
              aria-describedby="phone-help phone-error"
            />
            <p id="phone-help" class="field-help">Format: +1 (555) 000-0000 or 555-000-0000</p>
            <p id="phone-error" class="field-error" role="alert" hidden>
              Error: Enter a valid phone number, e.g. +1 (555) 000-0000 or 555-000-0000.
            </p>
          </div>

          <button type="submit" class="submit-btn">Send message</button>

        </form>

        <div id="success-message" class="success-message" hidden>
          <svg aria-hidden="true" focusable="false" class="success-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5">
            <circle cx="12" cy="12" r="10"/>
            <polyline points="9 12 11 14 15 10"/>
          </svg>
          <p>Your message has been sent. We&#8217;ll get back to you soon.</p>
        </div>
      </div>
    </main>

    <script>
(function () {
  'use strict';

  const form = document.getElementById('contact-form');
  const formStatus = document.getElementById('form-status');
  const successMessage = document.getElementById('success-message');

  const fields = {
    fullName: {
      input: document.getElementById('full-name'),
      error: document.getElementById('full-name-error'),
      validate(value) {
        if (!value.trim()) return 'Error: Full name is required.';
        return null;
      },
    },
    email: {
      input: document.getElementById('email'),
      error: document.getElementById('email-error'),
      validate(value) {
        if (!value.trim()) return 'Error: Email address is required.';
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
          return 'Error: Enter a valid email address, e.g. name@example.com.';
        }
        return null;
      },
    },
    phone: {
      input: document.getElementById('phone'),
      error: document.getElementById('phone-error'),
      validate(value) {
        if (!value.trim()) return null;
        if (!/^[+\d][\d\s\-().]{6,19}$/.test(value.trim())) {
          return 'Error: Enter a valid phone number, e.g. +1 (555) 000-0000 or 555-000-0000.';
        }
        return null;
      },
    },
  };

  function showError(field, message) {
    field.input.setAttribute('aria-invalid', 'true');
    field.error.textContent = message;
    field.error.hidden = false;
  }

  function clearError(field) {
    field.input.removeAttribute('aria-invalid');
    field.error.hidden = true;
    field.error.textContent = '';
  }

  function validateField(field) {
    const message = field.validate(field.input.value);
    if (message) {
      showError(field, message);
    } else {
      clearError(field);
    }
    return message;
  }

  Object.values(fields).forEach((field) => {
    field.input.addEventListener('blur', () => validateField(field));
    field.input.addEventListener('input', () => {
      if (field.input.getAttribute('aria-invalid') === 'true') {
        validateField(field);
      }
    });
  });

  form.addEventListener('submit', (event) => {
    event.preventDefault();

    const errors = Object.values(fields).map((field) => validateField(field));
    const firstErrorIndex = errors.findIndex((e) => e !== null);

    if (firstErrorIndex !== -1) {
      Object.values(fields)[firstErrorIndex].input.focus();
      return;
    }

    form.hidden = true;
    successMessage.hidden = false;
    formStatus.textContent = 'Your message has been sent. We\u2019ll get back to you soon.';
  });
})();
    </script>
  </body>
</html>
